#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
const int sensorPin = A0;
int sensorValue = 0;

void setup() {
lcd.begin();
lcd.backlight();
Serial.begin(9600);
}

void loop() {
sensorValue = analogRead(sensorPin);
lcd.setCursor(0, 0);
lcd.print("Humidite: ");
lcd.print(sensorValue);
lcd.print("%");
delay(1000);
}

